import{_ as a,o as i,c as e,ag as n}from"./chunks/framework.CxkNbRKf.js";const o="/nada-documentation/images/image155.png",s="/nada-documentation/images/image156.png",r="/nada-documentation/images/image157.png",l="/nada-documentation/images/image158.png",c="/nada-documentation/images/image159.png",d="/nada-documentation/images/image160.png",p="/nada-documentation/images/image161.png",h="/nada-documentation/images/image162.png",g="/nada-documentation/images/image163.png",m="/nada-documentation/images/image164.png",u="/nada-documentation/images/image165.png",f="/nada-documentation/images/image166.png",b="/nada-documentation/images/image167.png",_="/nada-documentation/images/image168.png",w="/nada-documentation/images/image169.png",y="/nada-documentation/images/image170.png",q="/nada-documentation/images/image171.png",U=JSON.parse('{"title":"Managing citations","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/citations.md","filePath":"admin-guide/web-ui/citations.md","lastUpdated":1786379412000}'),x={name:"admin-guide/web-ui/citations.md"};function P(A,t,k,v,I,S){return i(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="managing-citations" tabindex="-1">Managing citations <a class="header-anchor" href="#managing-citations" aria-label="Permalink to &quot;Managing citations&quot;">​</a></h1><p><img src="'+o+'" alt=""></p><p>Citations are the published and unpublished works that make use and cite datasets listed in your catalog. NADA provides the option to maintain a catalog of such citations.</p><p>Citations can be found in Semantics Scholar or Google Scholar. Or authors may inform you. Has to use multiple queries. Many false positives. Filter by year (exclude years &lt; dataset year). Requires some visual validation.</p><p>Can be a tedious process. We are developing a tool to assist.</p><p>Semantic scholar: <a href="https://www.semanticscholar.org/" target="_blank" rel="noreferrer">https://www.semanticscholar.org/</a></p><p>Advantage: open, has API</p><p><img src="'+s+'" alt=""></p><p>Google Scholar: <a href="https://scholar.google.com/" target="_blank" rel="noreferrer">https://scholar.google.com/</a></p><p>No API, and does not allow programmatic extraction. But convenient automated notification (alert).</p><p><img src="'+r+'" alt=""></p><p>Cannot guarantee exhaustivity and perfect accuracy. Data are poorly cited (no information on the version; translated or incomplete title mentioned in publications. Still can have much value to show that well documented and easily accessible data are used.</p><h2 id="adding-a-citation" tabindex="-1">Adding a citation <a class="header-anchor" href="#adding-a-citation" aria-label="Permalink to &quot;Adding a citation&quot;">​</a></h2><p>Citations are added from the Citations menu.</p><p>One citation can be related to more than one dataset. And of course, one dataset can have multiple citations. When you add a dataset to your catalog, and want to add citations to it, it may be the case that the citations was already entered but attached to another dataset. In such case, you will only have to add a dataset to the list of related datasets. You do not want to duplicate citations in your catalog.</p><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>To add a citation - click on All citations then click on the Add New Citation button at the top right.</p><p><img src="'+l+'" alt=""></p><p>It is important to know whether the citation is already in your citation catalog. Enter the title, possibly author, and the page will display the closest matches.</p><p>If no match, add the new citation by filling the citation form.</p><p><img src="'+c+'" alt=""></p><ul><li><p><strong>Citation type:</strong> Select the appropriate kind of publication. These were presented in the introduction of the manual. A drop-down list is provided.</p></li><li><p><strong>Title</strong>: Title of the document</p></li><li><p><strong>Authors</strong>: List of authors</p></li><li><p><strong>Edition</strong></p></li><li><p><strong>Volume</strong></p></li><li><p><strong>Publication date</strong>: Enter at least the year</p></li><li><p><strong>ISSN/ISBN/Other number</strong>: Unique identification number of the document (other than the DOI, for which a specific field is provided)</p></li><li><p><strong>Publisher</strong>: Name of the publisher</p></li><li><p><strong>City</strong>: City of the publisher address</p></li><li><p><strong>Country/State</strong>: Cuntry/State of the publisher address</p></li><li><p><strong>URL</strong>: Link to the document or to a page where the document is found</p></li><li><p><strong>DOI</strong>: Digital Object Identifier of the document</p></li><li><p><strong>Language</strong>: Language (if multiple, main language)</p></li><li><p><strong>Abstract</strong>: The abstract is optional, but we want to include it whenever possible. When copy/pasted from a PDF document, edit the content if necessary, to ensure that the flow of the text is continuous.</p><ul><li>Instead of:</li></ul></li></ul><p><img src="'+d+'" alt=""></p><ul><li>we want:</li></ul><p><img src="'+p+'" alt=""></p><ul><li><p><strong>Keywords</strong>: a list of keywords (entered in a single text field.</p></li><li><p><strong>Notes</strong>: additional notes, if any</p></li><li><p><strong>Attach file</strong>: Filename (with path) of the document (in most cases, this will not be provided; only the URL field will be filled)</p></li><li><p><strong>Flag</strong>: the flag will be used internally for adminisrtaive/review purpose. Citations that need review or confirmation for example can be flagged. The citations can be filtered by flag in the &quot;All citations&quot; page, allowing administrators and reviewers to take action accordingly.</p></li></ul><p><img src="'+h+'" alt=""></p><ul><li><strong>Publish</strong>: Publish (or not) the citation in the citation catalog.</li></ul><p>After entering all relevant information, click SAVE.</p><p>If the citation had already been entered (in which case it appears in the Similar citations box), you only have to attach an additional dataset to it. Select the citations in the &quot;Similar citations&quot; box (to avoid creating a duplicate). The form will be automatically filled out. Go to the <strong>Attach surveys</strong> tab to attach the relevant dataset(s), and save the change.</p><p><img src="'+g+'" alt=""></p><p>The citation (if the status has been set to &quot;Published&quot;) will now be visible in the user interface. The number of citations will be displayed in the catalog listings.</p><p><img src="'+m+'" alt=""></p><p>In a study page, the citations (if any) will be shown in a tab.</p><p><img src="'+u+'" alt=""></p><p>All citations will also be listed and searchable in the Citations catalog.</p><p><img src="'+f+'" alt=""></p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>...</p><h2 id="importing-citations" tabindex="-1">Importing citations <a class="header-anchor" href="#importing-citations" aria-label="Permalink to &quot;Importing citations&quot;">​</a></h2><p>It is also possible to import citations in common citation formats such as BibTex and EndNote (RIS).</p><h2 id="using-the-administrator-interface-1" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface-1" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>To do this use the Import Citations link from the top menu. Paste the BibTex or RIS text into the form and then at the bottom of the screen click on Attach studies to link the citation to a particular study in the catalog.</p><p><img src="'+b+'" alt=""></p><h2 id="using-the-api-1" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api-1" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>...</p><h2 id="exporting-citations" tabindex="-1">Exporting citations <a class="header-anchor" href="#exporting-citations" aria-label="Permalink to &quot;Exporting citations&quot;">​</a></h2><h2 id="using-the-administrator-interface-2" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface-2" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>The list of citations in your catalog can be exported to JSON or CSV format.</p><p><img src="'+_+'" alt=""></p><p><img src="'+w+'" alt=""></p><p>Citations exported as JSON:</p><p><img src="'+y+'" alt=""></p><p>Citations exported as CSV:</p><p><img src="'+q+'" alt=""></p><h2 id="using-the-api-2" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api-2" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>...</p><h2 id="deleting-citations" tabindex="-1">Deleting citations <a class="header-anchor" href="#deleting-citations" aria-label="Permalink to &quot;Deleting citations&quot;">​</a></h2><h2 id="using-the-administrator-interface-3" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface-3" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><h2 id="using-the-api-3" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api-3" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2>',60)])])}const T=a(x,[["render",P]]);export{U as __pageData,T as default};
